import{_ as a,o as i,c as s,ai as d}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"Python 面试 · 语言基础","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/basics-interview.md","filePath":"guide/python/basics-interview.md"}'),l={name:"guide/python/basics-interview.md"};function o(n,e,r,c,t,h){return i(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="python-面试-·-语言基础" tabindex="-1">Python 面试 · 语言基础 <a class="header-anchor" href="#python-面试-·-语言基础" aria-label="Permalink to “Python 面试 · 语言基础”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>可变与不可变类型？</li><li>列表推导式、字典推导式注意什么？</li><li>函数默认参数为什么别用可变对象？</li><li><code>is</code> 和 <code>==</code> 区别？</li><li>装饰器怎么理解？能写个简单的吗？</li><li>迭代器与生成器？</li><li>上下文管理器 <code>with</code> 解决什么？</li><li><code>*args</code> / <code>**kwargs</code> / 解包？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-可变-不可变" tabindex="-1">1）可变 / 不可变 <a class="header-anchor" href="#_1-可变-不可变" aria-label="Permalink to “1）可变 / 不可变”">​</a></h3><ul><li>不可变：<code>int</code>、<code>str</code>、<code>tuple</code> 等——「改」往往是生成新对象。</li><li>可变：<code>list</code>、<code>dict</code>、<code>set</code>——原地可改。<br> 影响：当字典 key、当默认参数、多处共享引用时的坑。</li></ul><h3 id="_2-推导式" tabindex="-1">2）推导式 <a class="header-anchor" href="#_2-推导式" aria-label="Permalink to “2）推导式”">​</a></h3><p>写法短，但别嵌太深；有副作用（写文件、请求）时用显式循环更清晰。<br> 大列表推导可能一次性占内存，必要时用生成器表达式 <code>(x for x in …)</code>。</p><h3 id="_3-默认参数陷阱" tabindex="-1">3）默认参数陷阱 <a class="header-anchor" href="#_3-默认参数陷阱" aria-label="Permalink to “3）默认参数陷阱”">​</a></h3><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> append_to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(item, bucket</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]):  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 错误示范：默认 list 只创建一次</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    bucket.append(item)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bucket</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>正确：<code>bucket=None</code>，函数里 <code>if bucket is None: bucket = []</code>。</p><h3 id="_4-is-vs" tabindex="-1">4）<code>is</code> vs <code>==</code> <a class="header-anchor" href="#_4-is-vs" aria-label="Permalink to “4）is vs ==”">​</a></h3><p><code>==</code> 比值；<code>is</code> 比是否同一对象。<br> 判空常用 <code>is None</code>，不要 <code>== None</code> 当风格问题也可提。</p><h3 id="_5-装饰器-口述-能写更好" tabindex="-1">5）装饰器（口述 + 能写更好） <a class="header-anchor" href="#_5-装饰器-口述-能写更好" aria-label="Permalink to “5）装饰器（口述 + 能写更好）”">​</a></h3><p>本质：接收函数、返回函数。<br> 用途：日志、鉴权、重试、计时。<br> 带参数的装饰器是「三层」：最外层收参数，中间收函数，内层收调用。</p><h3 id="_6-迭代器-生成器" tabindex="-1">6）迭代器 / 生成器 <a class="header-anchor" href="#_6-迭代器-生成器" aria-label="Permalink to “6）迭代器 / 生成器”">​</a></h3><p>迭代器：实现 <code>__iter__</code> / <code>__next__</code>。<br> 生成器：函数里 <code>yield</code>，自动做成迭代器，懒计算、省内存。</p><h3 id="_7-with" tabindex="-1">7）<code>with</code> <a class="header-anchor" href="#_7-with" aria-label="Permalink to “7）with”">​</a></h3><p>保证资源释放（文件、锁、连接）。<br><code>with open(...) as f</code> 离开代码块会关文件，比手写 <code>close</code> 稳。</p><h3 id="_8-解包" tabindex="-1">8）解包 <a class="header-anchor" href="#_8-解包" aria-label="Permalink to “8）解包”">​</a></h3><p><code>a, b = pair</code>；<code>*rest</code> 收集剩余；传参 <code>func(*args, **kwargs)</code> 拆开传入。</p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「<code>__init__</code> 和 <code>__new__</code>？」→ 知道 <code>__new__</code> 创建实例、<code>__init__</code> 初始化即可，不深抠除非岗位偏 Python。</li><li>「鸭子类型？」→ 不看继承看行为（有该方法就能用）；和 Java 强类型对比一嘴。</li></ul>`,26)])])}const k=a(l,[["render",o]]);export{_ as __pageData,k as default};
